B.eHj=s(["new","team"],t.s)
B.ebG=new A.cZ("t11",B.cJ,"Dream list","Write down three dreams each \u2014 for this year, for you two, for your life \u2014 and share them.","",B.eHj)
B.ezM=s(["close","steady"],t.s)
B.ec4=new A.cZ("t12",B.cJ,"Home",'Ask: "When do you feel most at home with me?"',"",B.ezM)
